mapper.select:
SELECT w.work_id, w.title, w.user_code, w.onedayclass_num, w.created_at, wi.image_url AS thumbnail_url FROM work w LEFT JOIN work_image wi ON w.work_id = wi.work_id AND wi.is_thumbnail = TRUE
w.onedayclass_num = #{onedayclass_num}
ORDER BY w.created_at DESC

SELECT *
FROM work_comment
WHERE parent_id IS NULL AND work_id = #{work_id}
ORDER BY comment_id
LIMIT #{limit} OFFSET #{offset}
